  // non-input binding (repository provisioning fans out over run context).
  const spec: DriverItemSpec = { unit_id_path: materialization.unit_id_path, depends_on_path: materialization.depends_on_path };
  let items: readonly DriverItem[];
  if (materialization.over.from === "input") {
